// ADRAirspaceExtensionInfo holds Eurocontrol ADR extension metadata (<adrext:AirspaceExtension>
// and <adrext:AirspaceActivationExtension>) extracted during XML unmarshalling.
type ADRAirspaceExtensionInfo struct {
	FlexibleUse          string
	Level1               string
	Level2               string
	Level3               string
	Usage                string
	IsFBZ                string
	DefaultForActivation string
	IsAMC                string
	ResponsibleAMCHref   string
	ResponsibleAMCTitle  string
	OwnerRSAHref         string
	OwnerRSATitle        string
	RequestorHref        string
	RequestorTitle       string
	HostAirspaceHrefs    []string
	RSAActivationCount   int
}

var (
	adrExtensionsMu sync.RWMutex
	adrExtensions   = make(map[string]*ADRAirspaceExtensionInfo)
)

// GetADRAirspaceExtension looks up Eurocontrol ADR extension metadata by AirspaceTimeSlice gml:id,
// Airspace gml:id, UUID identifier, or designator.
func GetADRAirspaceExtension(keys ...string) *ADRAirspaceExtensionInfo {
	adrExtensionsMu.RLock()
	defer adrExtensionsMu.RUnlock()
	for _, k := range keys {
		nk := strings.ToLower(strings.TrimSpace(k))
		nk = strings.TrimPrefix(nk, "urn:uuid:")
		nk = strings.TrimPrefix(nk, "#")
		if nk == "" {
			continue
		}
		if info, ok := adrExtensions[nk]; ok && info != nil {
			return info
		}
	}
	return nil
}

func extractADRExtensionsFromXML(data []byte) {
	dec := xml.NewDecoder(bytes.NewReader(data))
	parsed := make(map[string]*ADRAirspaceExtensionInfo)

	var currentAirspaceID string
	var currentIdentifier string
	var currentTSID string
	var currentDesig string
	var currentInfo *ADRAirspaceExtensionInfo
	inAirspaceTS := false
	inADRAirspaceExt := false
	inADRActivationExt := false
	var currentLeafTag string

	getAttr := func(attrs []xml.Attr, localName string) string {
		for _, a := range attrs {
			if a.Name.Local == localName {
				return strings.TrimSpace(a.Value)
			}
		}
		return ""
	}

	ensureInfo := func() *ADRAirspaceExtensionInfo {
		if currentInfo == nil {
			currentInfo = &ADRAirspaceExtensionInfo{}
		}
		return currentInfo
	}

	for {
		tok, err := dec.Token()
		if err != nil {
			break
		}
		switch t := tok.(type) {
		case xml.StartElement:
			switch t.Name.Local {
			case "Airspace":
				currentAirspaceID = getAttr(t.Attr, "id")
				currentIdentifier = ""
			case "AirspaceTimeSlice":
				inAirspaceTS = true
				currentTSID = getAttr(t.Attr, "id")
				currentDesig = ""
				currentInfo = nil
			case "AirspaceExtension":
				if inAirspaceTS {
					inADRAirspaceExt = true
				}
			case "AirspaceActivationExtension":
				if inAirspaceTS {
					inADRActivationExt = true
				}
			case "responsibleAMC":
				if inADRAirspaceExt {
					info := ensureInfo()
					info.ResponsibleAMCHref = getAttr(t.Attr, "href")
					info.ResponsibleAMCTitle = getAttr(t.Attr, "title")
				}
			case "ownerRSA":
				if inADRAirspaceExt {
					info := ensureInfo()
					info.OwnerRSAHref = getAttr(t.Attr, "href")
					info.OwnerRSATitle = getAttr(t.Attr, "title")
				}
			case "requestor":
				if inADRActivationExt {
					info := ensureInfo()
					info.RequestorHref = getAttr(t.Attr, "href")
					info.RequestorTitle = getAttr(t.Attr, "title")
				}
			case "hostAirspace":
				if inADRActivationExt {
					if href := getAttr(t.Attr, "href"); href != "" {
						info := ensureInfo()
						info.HostAirspaceHrefs = append(info.HostAirspaceHrefs, href)
					}
				}
			case "RSAActivation":
				if inADRActivationExt {
					info := ensureInfo()
					info.RSAActivationCount++
				}
			default:
				currentLeafTag = t.Name.Local
			}
		case xml.CharData:
			txt := strings.TrimSpace(string(t))
			if txt == "" {
				continue
			}
			if currentLeafTag == "identifier" && !inAirspaceTS && currentAirspaceID != "" {
				currentIdentifier = txt
			} else if inAirspaceTS && !inADRAirspaceExt && !inADRActivationExt && currentLeafTag == "designator" && currentDesig == "" {
				currentDesig = txt
			} else if inADRAirspaceExt {
				info := ensureInfo()
				switch currentLeafTag {
				case "flexibleUse":
					info.FlexibleUse = txt
				case "level1":
					info.Level1 = txt
				case "level2":
					info.Level2 = txt
				case "level3":
					info.Level3 = txt
				case "usage":
					info.Usage = txt
				case "isFBZ":
					info.IsFBZ = txt
				case "defaultForActivation":
					info.DefaultForActivation = txt
				case "isAMC":
					info.IsAMC = txt
				}
			}
		case xml.EndElement:
			switch t.Name.Local {
			case "AirspaceExtension":
				inADRAirspaceExt = false
			case "AirspaceActivationExtension":
				inADRActivationExt = false
			case "AirspaceTimeSlice":
				if currentInfo != nil {
					for _, rawKey := range []string{currentTSID, currentAirspaceID, currentIdentifier, "desig:" + currentDesig} {
						nk := strings.ToLower(strings.TrimSpace(rawKey))
						nk = strings.TrimPrefix(nk, "urn:uuid:")
						nk = strings.TrimPrefix(nk, "#")
						if nk != "" && nk != "desig:" {
							parsed[nk] = currentInfo
						}
					}
				}
				inAirspaceTS = false
				currentTSID = ""
				currentDesig = ""
				currentInfo = nil
			case "Airspace":
				currentAirspaceID = ""
				currentIdentifier = ""
			}
			currentLeafTag = ""
		}
	}

	if len(parsed) > 0 {
		adrExtensionsMu.Lock()
		for k, v := range parsed {
			adrExtensions[k] = v
		}
		adrExtensionsMu.Unlock()
	}
}

// UnmarshallXMLToStage unmarshals an XML document into stage (and its sub-stages),
// staging all reachable instances and assigning deterministic Gong Names.
func UnmarshallXMLToStage(stage *Stage, xmlBytes []byte) error {
	utf8Bytes := ensureUTF8XML(xmlBytes)
	extractADRExtensionsFromXML(utf8Bytes)
	rootElementName := detectRootXMLElementLocalName(utf8Bytes)

	switch rootElementName {
	case "AIXMBasicMessage":
		var rootObj AIXMBasicMessage
		if err := xml.Unmarshal(utf8Bytes, &rootObj); err != nil {
			return fmt.Errorf("xml unmarshal into AIXMBasicMessage failed: %w", err)
		}
		stage.StageBranch(&rootObj)
		propagateCrossStageBranches(stage)
		enforceInstanceNames(stage)
		return nil
	default:
		var rootObj AIXMBasicMessage
		if err := unmarshalXMLWithExpectedRoot(utf8Bytes, "AIXMBasicMessage", &rootObj); err != nil {
			return fmt.Errorf("xml unmarshal into AIXMBasicMessage failed: %w", err)
		}
		stage.StageBranch(&rootObj)
		propagateCrossStageBranches(stage)
		enforceInstanceNames(stage)
		return nil
	}
}

// MarshallStageToXML serializes the staged root XML element back to indented XML bytes.
func MarshallStageToXML(stage *Stage) ([]byte, error) {
	if insts := stage.GetInstancesSorted[*AIXMBasicMessage](); len(insts) > 0 {
		out, err := xml.MarshalIndent(insts[0], "", "  ")
		if err != nil {
			return nil, err
		}
		return append([]byte(xml.Header), out...), nil
	}
	return nil, fmt.Errorf("no root XML element instance is currently staged")
}

func detectRootXMLElementLocalName(data []byte) string {
	dec := xml.NewDecoder(bytes.NewReader(data))
	for {
		tok, err := dec.Token()
		if err != nil {
			if err == io.EOF {
				break
			}
			return ""
		}
		if se, ok := tok.(xml.StartElement); ok {
			return se.Name.Local
		}
	}
	return ""
}

func unmarshalXMLWithExpectedRoot(data []byte, expectedRootLocalName string, v any) error {
	dec := xml.NewDecoder(bytes.NewReader(data))
	for {
		tok, err := dec.Token()
		if err != nil {
			return err
		}
		if se, ok := tok.(xml.StartElement); ok {
			se.Name.Local = expectedRootLocalName
			se.Name.Space = ""
			return dec.DecodeElement(v, &se)
		}
	}
}

func ensureUTF8XML(data []byte) []byte {
	if len(data) >= 2 {
		// Check UTF-16 LE BOM (FF FE) or UTF-16 BE BOM (FE FF)
		if data[0] == 0xFF && data[1] == 0xFE {
			u16s := make([]uint16, (len(data)-2)/2)
			for i := range u16s {
				u16s[i] = uint16(data[2+2*i]) | (uint16(data[2+2*i+1]) << 8)
			}
			runes := utf16.Decode(u16s)
			out := string(runes)
			out = strings.Replace(out, "encoding=\"UTF-16\"", "encoding=\"UTF-8\"", 1)
			out = strings.Replace(out, "encoding='UTF-16'", "encoding='UTF-8'", 1)
			return []byte(out)
		}
		if data[0] == 0xFE && data[1] == 0xFF {
			u16s := make([]uint16, (len(data)-2)/2)
			for i := range u16s {
				u16s[i] = (uint16(data[2+2*i]) << 8) | uint16(data[2+2*i+1])
			}
			runes := utf16.Decode(u16s)
			out := string(runes)
			out = strings.Replace(out, "encoding=\"UTF-16\"", "encoding=\"UTF-8\"", 1)
			out = strings.Replace(out, "encoding='UTF-16'", "encoding='UTF-8'", 1)
			return []byte(out)
		}
	}
	return data
}

type goFileUploadCallback struct {
	stager *Stager
}

func (cb *goFileUploadCallback) OnFileUpload(loadedFile *load.FileToUpload) error {
	decodedBytes, err := base64.StdEncoding.DecodeString(loadedFile.Base64EncodedContent)
	if err != nil {
		log.Printf("Failed decoding base64 Go file: %v", err)
		return err
	}

	cb.stager.stage.Reset()
	if err := cb.stager.stage.ParseAstString(string(decodedBytes), true); err != nil {
		log.Printf("Failed parsing Multi-Stage Go AST: %v", err)
		return err
	}

	ext := filepath.Ext(loadedFile.Name)
	cb.stager.fileName = strings.TrimSuffix(loadedFile.Name, ext)
	cb.stager.stage.Commit()
	return nil
}

type xmlFileUploadCallback struct {
	stager *Stager
}

func (cb *xmlFileUploadCallback) OnFileUpload(loadedFile *load.FileToUpload) error {
	decodedBytes, err := base64.StdEncoding.DecodeString(loadedFile.Base64EncodedContent)
	if err != nil {
		log.Printf("Failed decoding base64 XML file: %v", err)
		return err
	}

	// Avoid overwriting data/stage.go with a massive file when a large XML dataset is dropped
	if len(decodedBytes) > 512*1024 {
		cb.stager.stage.OnInitCommitCallback = nil
	}

	cb.stager.stage.Reset()
	if err := UnmarshallXMLToStage(cb.stager.stage, decodedBytes); err != nil {
		log.Printf("Failed unmarshalling XML file: %v", err)
		return err
	}

	ext := filepath.Ext(loadedFile.Name)
	cb.stager.fileName = strings.TrimSuffix(loadedFile.Name, ext)
	cb.stager.stage.Commit()
	return nil
}

func (stager *Stager) ux_load() {
	stager.loadStageGo.Reset()
	fileToUploadGo := (&load.FileToUpload{
		Name:              "fileGo",
		FileToUploadProxy: &goFileUploadCallback{stager: stager},
	}).Stage(stager.loadStageGo)
	_ = fileToUploadGo
	(&load.Message{
		Name: "Drop Multi-Stage .go file here",
	}).Stage(stager.loadStageGo)
	stager.loadStageGo.Commit()

	stager.loadStageXML.Reset()
	fileToUploadXML := (&load.FileToUpload{
		Name:              "fileXML",
		FileToUploadProxy: &xmlFileUploadCallback{stager: stager},
	}).Stage(stager.loadStageXML)
	_ = fileToUploadXML
	(&load.Message{
		Name: "Drop .xml file here",
	}).Stage(stager.loadStageXML)
	stager.loadStageXML.Commit()
}

func (stager *Stager) exportGoFile() {
	log.Println("Button: Export MultiStage as Go file")
	stager.loadStageGo.Reset()

	stager.stage.ComputeReferenceAndOrders()
	data, err := stager.stage.MarshallToString("", "main")
	if err != nil {
		log.Printf("Error marshalling MultiStage to Go string: %v", err)
		return
	}

	baseName := stager.fileName
	if baseName == "" {
		baseName = "stage"
	}
	encoded := base64.StdEncoding.EncodeToString([]byte(data))
	(&load.FileToDownload{
		Name:                 baseName + ".go",
		Base64EncodedContent: encoded,
	}).Stage(stager.loadStageGo)

	stager.loadStageGo.Commit()
}

func (stager *Stager) exportXMLFile() {
	log.Println("Button: Export XML")
	stager.loadStageXML.Reset()

	xmlBytes, err := MarshallStageToXML(stager.stage)
	if err != nil {
		log.Printf("Error marshalling Stage to XML: %v", err)
		return
	}

	baseName := stager.fileName
	if baseName == "" {
		baseName = "document"
	}
	encoded := base64.StdEncoding.EncodeToString(xmlBytes)
	(&load.FileToDownload{
		Name:                 baseName + ".xml",
		Base64EncodedContent: encoded,
	}).Stage(stager.loadStageXML)

	stager.loadStageXML.Commit()
}

func (stager *Stager) ux_button() {
	stager.buttonStage.Reset()

	layout := new(button.Layout).Stage(stager.buttonStage)
	group1 := new(button.Group).Stage(stager.buttonStage)
	group1.Percentage = 100
	layout.Groups = append(layout.Groups, group1)

	btnExportGo := (&button.Button{
		Name:        "Export MultiStage as Go file",
		Icon:        string(tree_buttons.BUTTON_fact_check),
		Label:       "Export MultiStage as Go file",
		HasToolTip:  true,
		ToolTipText: "Serialize all packages/stages to a single deterministic Go file",
		OnClick: func() {
			stager.mu.Lock()
			defer stager.mu.Unlock()
			stager.exportGoFile()
		},
	}).Stage(stager.buttonStage)

	btnExportXML := (&button.Button{
		Name:        "Export XML",
		Icon:        string(tree_buttons.BUTTON_code),
		Label:       "Export XML",
		HasToolTip:  true,
		ToolTipText: "Serialize the root document element to an XML file",
		OnClick: func() {
			stager.mu.Lock()
			defer stager.mu.Unlock()
			stager.exportXMLFile()
		},
	}).Stage(stager.buttonStage)

	btnToggle3D := (&button.Button{
		Name:        "Toggle 2D / 3D Airspace Volumes",
		Icon:        string(tree_buttons.BUTTON_visibility),
		Label:       "Toggle 2D / 3D Volumes",
		HasToolTip:  true,
		ToolTipText: "Switch MapLibre between 2D Aeronautical Chart and 3D Extruded Airspace Volumes",
		OnClick: func() {
			stager.mu.Lock()
			defer stager.mu.Unlock()
			stager.extrude3D = !stager.extrude3D
			stager.ux_maplibre()
		},
	}).Stage(stager.buttonStage)

	group1.Buttons = append(group1.Buttons, btnExportGo, btnExportXML, btnToggle3D)

	stager.buttonStage.Commit()
}
